const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
const path = require('path');

const SIZES = [
  ['square', 1080, 1080],
  ['landscape', 1920, 1080],
  ['story', 1080, 1920],
];

const SEL = ['.header', '.header img', '.event', '.avatar', '.name', '.role', '.title', '.when', '.cta'];

(async () => {
  const browser = await chromium.launch();
  let bad = 0;
  for (const [name, w, h] of SIZES) {
    const page = await browser.newPage({ viewport: { width: w, height: h } });
    await page.goto('file://' + path.resolve(__dirname, 'card.html'));
    await page.waitForFunction(() => document.fonts.status === 'loaded');
    await page.waitForTimeout(250);

    const res = await page.evaluate((SEL) => {
      const out = { boxes: {}, issues: [], fontOK: document.fonts.check('700 60px Inter') };
      for (const s of SEL) {
        const el = document.querySelector(s);
        const r = el.getBoundingClientRect();
        out.boxes[s] = { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) };
        // clipped inside its own box (text overflow)?
        if (el.scrollWidth > Math.ceil(r.width) + 1) out.issues.push(`${s}: scrollWidth ${el.scrollWidth} > width ${r.width.toFixed(1)}`);
        if (el.scrollHeight > Math.ceil(r.height) + 1) out.issues.push(`${s}: scrollHeight ${el.scrollHeight} > height ${r.height.toFixed(1)}`);
        // outside viewport?
        if (r.left < -0.5 || r.top < -0.5 || r.right > innerWidth + 0.5 || r.bottom > innerHeight + 0.5)
          out.issues.push(`${s}: outside viewport (${r.left.toFixed(1)},${r.top.toFixed(1)},${r.right.toFixed(1)},${r.bottom.toFixed(1)})`);
      }
      // page-level scroll
      const de = document.documentElement;
      if (de.scrollWidth > innerWidth + 1 || de.scrollHeight > innerHeight + 1)
        out.issues.push(`document scrolls: ${de.scrollWidth}x${de.scrollHeight}`);

      // pairwise overlap of text/visual blocks
      const pairs = ['.header', '.avatar', '.name', '.role', '.title', '.when', '.cta'];
      for (let i = 0; i < pairs.length; i++)
        for (let j = i + 1; j < pairs.length; j++) {
          const a = document.querySelector(pairs[i]).getBoundingClientRect();
          const b = document.querySelector(pairs[j]).getBoundingClientRect();
          const ox = Math.min(a.right, b.right) - Math.max(a.left, b.left);
          const oy = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
          if (ox > 1 && oy > 1) out.issues.push(`OVERLAP ${pairs[i]} / ${pairs[j]} (${ox.toFixed(1)}x${oy.toFixed(1)})`);
        }

      // circle check
      const av = document.querySelector('.avatar');
      const ar = av.getBoundingClientRect();
      if (Math.abs(ar.width - ar.height) > 0.5) out.issues.push(`avatar not square: ${ar.width}x${ar.height}`);
      const br = getComputedStyle(av).borderTopLeftRadius;
      out.radius = br;

      out.titleLines = Math.round(document.querySelector('.title').getClientRects().length);
      return out;
    }, SEL);

    console.log(`\n===== ${name} ${w}x${h} =====`);
    console.log('Inter loaded:', res.fontOK, '| avatar radius:', res.radius, '| title line boxes:', res.titleLines);
    for (const [k, v] of Object.entries(res.boxes)) console.log(`  ${k.padEnd(12)} x=${v.x} y=${v.y} w=${v.w} h=${v.h}`);
    if (res.issues.length) { bad += res.issues.length; res.issues.forEach(i => console.log('  !! ' + i)); }
    else console.log('  OK — no overflow, no overlap, all inside frame');
    await page.close();
  }
  await browser.close();
  console.log(bad ? `\nTOTAL ISSUES: ${bad}` : '\nALL CLEAN');
})();

